"""Regression coverage for src/scripts/extract-style-metrics.py and its
src/scripts/lib/style_*.py modules.

Each test here pins a defect found by running :init on a real Hebrew corpus
(10 files / 48k words, supervisor-returned .docx among them):

  1. tracked <w:ins> insertions were folded into the author's fingerprint
  2. the baseline JSON fence was selected by a Latin-only heading match, so a
     Hebrew heading fell through to the first fence in the file, silently
  3. the .docx reader joined <w:p> with one newline while the paragraph
     splitter wants a blank line, so every file counted as ONE paragraph
  4. HTML entities were never unescaped, so "quot" outranked every real word
     in frequentTerms
  5. the Hebrew passive-voice heuristic flagged any 3+ letter word opening
     with נ or מ

Synthetic .docx fixtures are built with stdlib zipfile: the reader only ever
reads word/document.xml, so no python-docx dependency is needed here.
"""

from __future__ import annotations

import os
import sys
import unittest
import zipfile

ROOT_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
LIB_DIR = os.path.join(ROOT_DIR, "src", "scripts", "lib")
if LIB_DIR not in sys.path:
    sys.path.insert(0, LIB_DIR)

from style_contrastive import extract_baseline_json  # noqa: E402
from style_frequent_terms import compute_frequent_terms  # noqa: E402
from style_metrics_core import (  # noqa: E402
    compute_computational_metrics,
    split_paragraphs,
)
from style_text_extraction import _read_docx_text  # noqa: E402

DOC_OPEN = (
    '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
    '<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">'
    "<w:body>"
)
DOC_CLOSE = "</w:body></w:document>"


def _para(*runs: str) -> str:
    return "<w:p>" + "".join(runs) + "</w:p>"


def _run(text: str) -> str:
    return f"<w:r><w:t>{text}</w:t></w:r>"


def _ins(author: str, text: str) -> str:
    return f'<w:ins w:id="1" w:author="{author}">{_run(text)}</w:ins>'


def _del(author: str, text: str) -> str:
    return (
        f'<w:del w:id="2" w:author="{author}">'
        f"<w:r><w:delText>{text}</w:delText></w:r></w:del>"
    )


def _make_docx(tmpdir: str, body: str, name: str = "sample.docx") -> str:
    path = os.path.join(tmpdir, name)
    with zipfile.ZipFile(path, "w") as zf:
        zf.writestr("word/document.xml", DOC_OPEN + body + DOC_CLOSE)
    return path


class TrackedChangesTest(unittest.TestCase):
    """Bug 1 — a supervisor's tracked insertions are not the author's voice."""

    def test_insertions_and_deletions_are_excluded(self):
        import tempfile

        body = _para(
            _run("המחבר כתב משפט."),
            _ins("Supervisor", "יש להפנות למקורות הידע בהערות שוליים!"),
            _del("Supervisor", "טקסט שנמחק"),
            _run(" סוף."),
        )
        with tempfile.TemporaryDirectory() as tmp:
            text = _read_docx_text(_make_docx(tmp, body))
        self.assertIn("המחבר כתב משפט.", text)
        self.assertIn("סוף.", text)
        self.assertNotIn("הערות שוליים", text)
        self.assertNotIn("טקסט שנמחק", text)

    def test_nested_revision_containers_are_removed(self):
        import tempfile

        nested = (
            '<w:ins w:id="3" w:author="Reviewer">'
            + _run("outer insertion")
            + _del("Reviewer", "inner deletion")
            + "</w:ins>"
        )
        with tempfile.TemporaryDirectory() as tmp:
            text = _read_docx_text(_make_docx(tmp, _para(_run("kept."), nested)))
        self.assertIn("kept.", text)
        self.assertNotIn("outer insertion", text)
        self.assertNotIn("inner deletion", text)


class ParagraphSplittingTest(unittest.TestCase):
    """Bug 3 — <w:p> must produce a blank line, not a single newline."""

    def test_each_w_p_becomes_its_own_paragraph(self):
        import tempfile

        body = "".join(
            _para(_run(f"פסקה מספר {n}. משפט שני בפסקה.")) for n in range(1, 6)
        )
        with tempfile.TemporaryDirectory() as tmp:
            text = _read_docx_text(_make_docx(tmp, body))
        self.assertEqual(len(split_paragraphs(text)), 5)
        metrics = compute_computational_metrics(text)
        self.assertEqual(metrics["paragraphStructure"]["count"], 5)

    def test_paragraph_length_is_not_the_whole_file(self):
        import tempfile

        body = "".join(_para(_run("משפט אחד בלבד.")) for _ in range(10))
        with tempfile.TemporaryDirectory() as tmp:
            text = _read_docx_text(_make_docx(tmp, body))
        metrics = compute_computational_metrics(text)
        self.assertEqual(metrics["paragraphStructure"]["count"], 10)
        self.assertLess(metrics["paragraphStructure"]["sentencesPerParagraph"]["mean"], 3)


class HtmlEntityTest(unittest.TestCase):
    """Bug 4 — escaped gershayim made "quot" the top content term."""

    def test_entities_are_unescaped_in_docx_text(self):
        import tempfile

        body = _para(_run("הוא אמר &quot;שלום&quot; ואז יצא &amp; חזר."))
        with tempfile.TemporaryDirectory() as tmp:
            text = _read_docx_text(_make_docx(tmp, body))
        self.assertNotIn("quot", text)
        self.assertNotIn("&amp;", text)
        self.assertIn('"שלום"', text)

    def test_entity_remnants_never_reach_frequent_terms(self):
        text = " ".join(["&quot;"] * 50 + ["מחקר"] * 10)
        terms = [t["term"] for t in compute_frequent_terms(text, 10, 2)]
        self.assertNotIn("quot", terms)
        self.assertIn("מחקר", terms)


class BaselineSelectionTest(unittest.TestCase):
    """Bug 2 — the shipped Hebrew baseline has a Hebrew heading."""

    HEBREW_DOC = """# מדריך לשוני עברי

## נספח א — נתוני ייחוס

```json
{"unrelated": {"foo": 1}}
```

## פרופיל בסיס לטביעת אצבע סגנונית

```json
{"sentenceLevel": {"length": {"mean": 21.4}, "passiveVoiceFrequency": 0.19},
 "vocabulary": {"typeTokenRatio": 0.41, "avgWordLength": 4.8}}
```
"""

    def test_hebrew_heading_still_finds_the_metrics_fence(self):
        payload, warnings = extract_baseline_json(self.HEBREW_DOC)
        self.assertIsNotNone(payload)
        self.assertEqual(payload["sentenceLevel"]["length"]["mean"], 21.4)
        self.assertNotIn("unrelated", payload)
        self.assertEqual(warnings, [])

    def test_fallback_to_a_non_baseline_fence_warns(self):
        payload, warnings = extract_baseline_json(
            "# כותרת\n\n```json\n{\"unrelated\": 1}\n```\n"
        )
        self.assertEqual(payload, {"unrelated": 1})
        self.assertTrue(warnings, "silent fallback must emit a warning")
        self.assertIn("falling back", warnings[0])

    def test_no_fence_returns_none_without_warning(self):
        payload, warnings = extract_baseline_json("# כותרת\n\nאין כאן JSON.\n")
        self.assertIsNone(payload)
        self.assertEqual(warnings, [])


class PassiveVoiceTest(unittest.TestCase):
    """Bug 5 — the נ/מ prefix heuristic flagged ordinary Hebrew nouns."""

    def test_hebrew_corpus_reports_null_not_a_guess(self):
        text = (
            "המחקר הזה בוחן מקורות שונים. מאמר זה מציג נושא מרכזי. "
            "מקום המחקר נקבע מראש. נושאים נוספים מופיעים בהמשך."
        )
        sentence_level = compute_computational_metrics(text)["sentenceLevel"]
        self.assertIsNone(sentence_level["passiveVoiceFrequency"])
        self.assertIn("passiveVoiceFrequencyNote", sentence_level)

    def test_english_corpus_still_gets_a_number(self):
        text = (
            "The claim was examined by three reviewers. "
            "This section presents the argument. "
            "The data were collected over two years."
        )
        sentence_level = compute_computational_metrics(text)["sentenceLevel"]
        self.assertIsInstance(sentence_level["passiveVoiceFrequency"], float)
        self.assertGreater(sentence_level["passiveVoiceFrequency"], 0.0)
        self.assertNotIn("passiveVoiceFrequencyNote", sentence_level)


if __name__ == "__main__":
    unittest.main()
